// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2001, "10-11", [{"author":"Л. Фёдорова","question":"Во фразе «<em>Есть в три горла</em>» слово <em>три</em> означает ‘много’, а во фразе «<em>У него всё образование — три класса и коридор</em>» <em>—</em> ‘мало’. А в каких из этих пяти примеров <em>три</em> означает ‘много’: 1) <em>в трёх соснах</em>, 2) <em>в три ручья</em>, 3) <em>в три шеи</em>, 4) <em>в три погибели</em>, 5) <em>втридорога</em>?","choices":["во всех","во всех, кроме 1","в 2","в 3 и 4","в 2 и 4."],"key":"Б","review":["Много или мало","В трёх соснах может заблудиться лишь тот, кто не справляется даже с малым. Здесь три — небольшое число.","Плакать в три ручья, гнать в три шеи, согнуться в три погибели, купить втридорога — усиления. Нужны все выражения, кроме первого."]},{"author":"И. Рубанов","question":"Сказуемое во фразе: «<em>Вовочка слинял с уроков</em>» – это … .","choices":["<em>архаизм</em>","<em>жаргонизм</em>","<em>латинизм</em>","<em>просторечное слово</em>","<em>диалектизм</em>."],"key":"Б","review":["С урока слиняли","Сравни нейтральное «Вовочка ушёл с уроков» и намеренно неофициальное «слинял». Значение «незаметно удрал» принадлежит сниженной речи.","В предложенной классификации это жаргонизм, относящийся к речевой манере, а не к определённой местности или эпохе."]},{"author":"Н. Муравенко","question":"В известной математической шутке некая кривая определяется как «окружность, вписанная в квадрат 3 на 4». Эта кривая на самом деле называется … .","choices":["<em>эллипс</em>","<em>элипс</em>","<em>эллепс</em>","<em>эллибз</em>","<em>эллебс</em>."],"key":"А","review":["Кривая из шутки","Если растянуть окружность вместе с рисунком так, чтобы квадрат стал прямоугольником, получится эллипс.","Название пишется с двумя л, буквой и и окончанием на -пс: «эллипс»."]},{"author":"Е. Муравенко","question":"Начался концерт. Прошло 5 минут, и прозвучала известная мелодия. После концерта пять слушателей рассказали об этом так: 1) <em>Через пять минут прозвучала мелодия</em>. 2) <em>Пятью минутами позже прозвучала мелодия</em>. 3) <em>Пятью минутами спустя прозвучала мелодия</em>. 4) <em>Пять минут спустя прозвучала мелодия</em>. 5) <em>Спустя пять минут прозвучала мелодия</em>. Кто из них построил фразу правильно?","choices":["все","все, кроме 3","все, кроме 2, 3","все, кроме 3, 4","1, 5."],"key":"Б","review":["После начала концерта","«Через пять минут» и «пять минут спустя», как и «спустя пять минут», требуют винительного падежа. «Пятью минутами позже» допускает творительный при сравнительном «позже».","В третьей фразе «пятью минутами спустя» эти два способа смешаны. Верны все варианты, кроме 3."]},{"author":"Л. Фёдорова","question":"Пословица: «<em>Рука руку …</em>» оканчивается глаголом … .","choices":["<em>кроет</em>","<em>мажет</em>","<em>моет</em>","<em>тянет</em>","<em>манит</em>."],"key":"В","review":["Рука руку…","Вспомни, что делают руки, помогая одна другой при умывании. Этот образ переносится на взаимную поддержку, часто небескорыстную.","Устойчивое выражение звучит «рука руку моет»."]},{"author":"Н. Муравенко","question":"В каких словах из приведённых на месте многоточия пишется <em>-уу-</em>: 1) <em>опосс…м</em>, 2) <em>индивид…м</em>, 3) <em>уник…м</em>, 4) <em>постскрипт…м</em>, (5) <em>вак…м</em>?","choices":["1, 2, 5","2, 5","2, 4, 5","1, 2","3, 5."],"key":"Б","review":["Две буквы у","Проверим полные написания: «опоссум», «индивидуум», «уникум», «постскриптум», «вакуум».","Два у подряд оказываются только в словах «индивидуум» и «вакуум» — номера 2 и 5."]},{"author":"Л. Фёдорова","question":"Посмотрите на список слов: 1) <em>распетушиться</em>, 2) <em>съёжиться</em>, 3) <em>ишачить</em>, 4) <em>обезьянничать</em>, 5) <em>ощениться</em>, 6) <em>проворонить</em>, 7) <em>насвинячить</em>, 8) <em>присобачить</em>, 9) <em>окрыситься</em>, 10) <em>опороситься</em>. Какие из них не означают ‘вести себя, как существо, обозначенное корнем слова’?","choices":["5, 9, 10","5, 10","6, 8","5, 6, 8, 9, 10","5, 6, 8, 10."],"key":"Д","review":["Названия животных в глаголах","«Ощениться» и «опороситься» называют появление детёнышей. «Проворонить» — упустить, «присобачить» — прикрепить.","Эти четыре глагола не требуют понимания «вести себя подобно такому животному». Искомые номера 5, 6, 8 и 10."]},{"author":"Л. Фёдорова","question":"Вот шесть слов: 1) <em>очевидно</em>, 2) <em>заочный</em>, 3) <em>воочию</em>, 4) <em>разочароваться</em>, 5) <em>очутиться</em>, 6) <em>очки</em>. Какие из них исторически произошли от общего корня?","choices":["все","все, кроме 5","все, кроме 5, 6","все, кроме 2, 5, 6","все, кроме 4, 5."],"key":"Д","review":["Родня «ока»","«Очевидно» — видно глазами, «заочный» — без личного присутствия, «воочию» — собственными глазами. «Очки» тоже связаны с древним словом «око».","Одинаковое начало в «разочароваться» и «очутиться» такой связи не создаёт. Исключаем именно 4 и 5."]},{"author":"Е. Муравенко","question":"Кто написал роман, название которого здесь зашифровано?","choices":["<em>Булгаков</em>","<em>Достоевский</em>","<em>Толстой</em>","<em>Тургенев</em>","<em>Гончаров</em>."],"key":"Б","review":["Название романа","Начальную П соединяем с нотой ре. У рисунка стула знак с номерами указывает на изменение его названия. Дальше изменения изображённых слов продолжают название.","В ребусе зашифровано «Преступление и наказание». Этот роман написал Фёдор Михайлович Достоевский."],"figure":{"condition":{"src":"assets/medvezhonok/2001/figures/10-11-09.webp","detailSrc":"assets/medvezhonok/2001/figures/10-11-09-detail.webp","alt":"Последовательность рисунков и знаков, образующая название романа.","pixelWidth":680,"pixelHeight":155}}},{"author":"Л. Фёдорова","question":"Даны четыре фразы: — <em>Однако</em> (1) <em>я скрывать не стану</em>. — <em>Не стану я скрывать</em> (2) <em>однако</em>. — <em>Скрывать</em> (3) <em>однако</em> (4) <em>я не стану</em>. — <em>Ты скрыл</em> (5) <em>однако</em> (6) <em>я не скрою</em>. Где в местах, отмеченных цифрами, нужна запятая?","choices":["везде","1, 5","2, 3, 4","2, 3, 4, 5","2, 3, 4, 6."],"key":"Г","review":["Однако где запятая","В начале первой фразы «однако» равнозначно союзу «но» и запятой после себя не требует. В конце второй и в середине третьей это вводное слово.","В четвёртой «однако» соединяет две части предложения, нужна запятая перед союзом. Получаем позиции 2, 3, 4 и 5."]},{"author":"Е. Муравенко","question":"Каждое из пяти приведённых ниже слов употреблено в прямом и переносном значениях. В каком из слов перенос значения произошёл не по тому признаку, что во всех остальных?","choices":["<em>колокольчик (звенит колокольчик — цветёт колокольчик)</em>","<em>класс (дружный класс — просторный класс)</em>","<em>шапка (вязаная шапка — шапка снега)</em>","<em>яблоко (вкусное яблоко — глазное яблоко)</em>","<em>игла (швейная игла — сосновая игла)</em>."],"key":"Б","review":["Как переносится значение","Колокольчик-цветок напоминает колокольчик формой, шапка снега — головной убор; глазное яблоко и сосновая игла тоже названы по сходству формы.","«Класс» как группа учеников и как помещение — перенос по связи людей с местом занятий. Это другое основание."]},{"author":"Л. Фёдорова","question":"В ряду <em>тетрадь, тетраэдр, терраса, квартет, квартал, квадрат, четверг</em> между всеми словами, кроме одного, есть некая смысловая связь. Какое же слово лишнее?","choices":["<em>квадрат</em>","<em>тетрадь</em>","<em>тетраэдр</em>","<em>терраса</em>","<em>четверг</em>."],"key":"Г","review":["Где спрятана четвёрка","Греческое tetra- и латинское quart- связаны с четырьмя. Эта связь есть у тетради, тетраэдра, квартета, квартала и квадрата. «Четверг» тоже связан со счётом.","«Терраса» восходит к слову со значением «земля». Она одна не входит в эту группу."]},{"author":"И. Рубанов","question":"Даны слова: 1) <em>оптимальные</em>; 2) <em>самые оптимальные</em>; 3) <em>наилучшие</em>; 4) <em>самые наилучшие</em>; 5) <em>самые хорошие</em>. Какие из них можно подставить вместо многоточия во фразу: <em>Для работы были созданы ... условия</em>?","choices":["все","2, 4, 5","3, 4, 5","1, 3, 5","1, 3, 4, 5."],"key":"Г","review":["Лучшие условия","«Оптимальные» уже означает наиболее подходящие, а «наилучшие» уже называет высшую степень. Добавление «самые» удваивает это значение.","Нормативно в рамках задания: «оптимальные», «наилучшие», «самые хорошие». Это 1, 3 и 5."]},{"author":"Л. Фёдорова","question":"Какое из данных мужских имён, имеющих общее происхождение, распространено только в Венгрии?","choices":["<em>Чарльз</em>","<em>Карл</em>","<em>Карой</em>","<em>Карло</em>","<em>Шарль</em>."],"key":"В","review":["Имя по-венгерски","Одно старое имя дало разные национальные формы: Карл, Шарль, Чарльз. Венгерское Károly передают на русском как «Карой».","Выбираем Карой. Имя узнаётся по языковой форме, а не по месту жительства конкретного человека."]},{"author":"Л. Фёдорова","question":"Какая из частиц указывает на голландскую фамилию?","choices":["<em>Мак</em>","<em>О’</em>","<em>бен</em>","<em>ван</em>","<em>фон</em>."],"key":"Г","review":["Частица в фамилии","В нидерландских фамилиях перед основной частью часто стоит van, буквально «из, от». Пример — Винсент ван Гог.","В русской передаче это «ван». Немецкую частицу von передают иначе — «фон»."]},{"author":"Л. Фёдорова","question":"История неразрывно связала некоторые имена и понятия: <em>геростратова слава, пиррова победа…</em> Вот шесть имен: <em>Ахиллес</em>, <em>Геркулес</em>, <em>Дамокл</em>, <em>Прокруст</em>, <em>Сизиф</em>, <em>Эзоп</em>. А вот восемь понятий: 1) <em>труд</em>, 2) <em>язык</em>, 3) <em>каша</em>, 4) <em>кинжал</em>, 5) <em>ложе</em>, 6) <em>столбы</em>, 7) <em>пята</em>, 8) <em>меч</em>. Какие из восьми понятий не связаны ни с одним из шести имен?","choices":["6, 8","4, 6","3, 4","3, 8","4, 2."],"key":"В","review":["Шесть имён и восемь слов","У Ахиллеса пята, у Геркулеса столбы, над Дамоклом меч, у Прокруста ложе. Сизифов труд и эзопов язык дополняют набор.","Даже если «геркулес» напоминает овсяную кашу, искомое устойчивое историко-мифологическое сочетание — «геркулесовы столбы». Лишние номера 3 и 4: каша, кинжал."]},{"author":"И. Рубанов","question":"Депутат Сидоров на выборах в Городское Собрание набрал 7245 голосов. Сколькими голосами он был избран?","choices":["<em>семь тысяч двести сорока пятью</em>","<em>семью тысячами двухстами сорока пятью</em>","<em>семи тысячами двумястами сорока пятью</em>","<em>семью тысячами двумястами сорока пятью</em>","<em>семью тысячами двести сорока пятью</em>."],"key":"Г","review":["Сколькими голосами","В составном числительном склоняем каждую часть: семью тысячами, двумястами, сорока, пятью.","Вместе получается «семью тысячами двумястами сорока пятью голосами»."]},{"author":"К. Кноп","question":"В слове <em>документ</em> ударение должно ставиться на последний слог, а любое другое ударение считается грубой ошибкой. Найдите среди перечисленных слов все слова с таким же свойством: 1) <em>регламент,</em> 2) <em>аргумент,</em> 3) <em>инструмент,</em> 4) <em>орнамент,</em> 5) <em>ассортимент,</em> 6) <em>парламент.</em>","choices":["2 и 3","2, 3 и 5","2, 3, 4 и 5","все слова","2 и 5."],"key":"Б","review":["Ударный последний слог","Произнеси слова: регла́мент, аргуме́нт, инструме́нт, орна́мент, ассортиме́нт, парла́мент.","На последнем слоге ударение в «аргуме́нт», «инструме́нт», «ассортиме́нт». Это 2, 3 и 5."]},{"author":"Я. Миронов","question":"Выберите фразу, где нет орфографических ошибок:","choices":["<em>Импрессарио посчитал условия неприемлимыми и остался за рубежом</em>.","<em>Импресарио посчитал условия неприемлемыми и остался за рубежом</em>.","<em>Импресарио посчитал условия неприемлимыми и остался зарубежом</em>.","<em>Имприссарио посчитал условия неприемлимыми и остался за рубежом</em>.","<em>Импресарио посчитал условия неприемлимыми и остался за рубежом</em>."],"key":"Б","review":["Проверяем написание","У «импресарио» одна с, в слове «неприемлемыми» пишем -емл-, сочетание «за рубежом» состоит из двух слов.","Все три написания соблюдены в предложении «Импресарио посчитал условия неприемлемыми и остался за рубежом»."]},{"author":"Е. Муравенко","question":"Какой тип придаточного представлен в сложноподчинённом предложении: <em>Сергей стремился в Петербург, где прошли годы его юности</em>?","choices":["<em>присоединительное</em>","<em>места</em>","<em>изъяснительное</em>","<em>определительное</em>","<em>причины</em>."],"key":"Г","review":["Какой именно Петербург","Придаточная часть «где прошли годы его юности» относится к существительному «Петербург». Её можно переформулировать с «в котором».","Она даёт признак названного города и является определительной. Само слово «где» не делает придаточное обстоятельственным."]},{"author":"Е. Муравенко","question":"Сколько раз встречаются звуки [б], [п] и [в] в пословице: «<em>Без труда не выловишь и рыбку из пруда</em>»?","choices":["[б] – 0, [п] – 2, [в] – 1","[б] – 1, [п] – 2, [в] – 2","[б] – 1, [п] – 1, [в] – 1","[б] – 2, [п] – 1, [в] – 1","[б] – 2, [п] – 1, [в] – 0."],"key":"А","review":["Считаем твёрдые звуки","В «без» б мягкий, поэтому твёрдый [б] не считаем. В «рыбку» буква б перед к обозначает [п], ещё один [п] слышен в «пруда».","В «выловишь» первое в твёрдое, второе — мягкое. Получаем [б] — 0, [п] — 2, [в] — 1."]},{"author":"Л. Фёдорова","question":"От какой основы слова или псевдослова не могло бы произойти слово <em>букашка</em>?","choices":["бука","букан","букага","*букаха","*букаша."],"key":"В","review":["Откуда взялось «ш»","Перед уменьшительным суффиксом х может переходить в ш, а г обычно чередуется с ж. Основа на ш уже содержит нужный звук; возможны и другие суффиксальные модели, как «бумага — бумажка».","От условного «букага» по такому образцу получилось бы «букажка», а не «букашка». Это и есть лишняя основа."]},{"author":"Л. Фёдорова","question":"Какие из названий дней недели нерусского происхождения?","choices":["все русские","<em>среда</em>","<em>четверг</em>","<em>суббота</em>","<em>среда</em> и <em>суббота</em>."],"key":"Д","review":["Два дня недели","Современная форма «среда» пришла из старославянского; рядом существует русская полногласная «середа». «Суббота» в конечном счёте восходит к названию шаббата.","В историко-этимологическом смысле подходят и среда, и суббота."]},{"author":"Е. Муравенко","question":"Сколько различных смыслов имеет предложение <em>Белые лилии и розы сменили обычные ромашки</em>?","choices":["1","2","3","4","5."],"key":"Г","review":["Что сменило цветы","«Лилии и розы» и «ромашки» могут стоять и в именительном, и в винительном падеже. Потому без контекста возможны оба направления замены.","Белыми могут быть только лилии или лилии вместе с розами. Две неоднозначности дают четыре сочетания."]},{"author":"Е. Муравенко","question":"Определите род существительных <em>топорище</em> и <em>пожарище</em>.","choices":["оба мужского рода","оба среднего рода","<em>топорище</em> — мужского рода, <em>пожарище</em> — среднего рода","<em>топорище</em> — среднего рода, <em>пожарище</em> — мужского рода","оба слова мужского или среднего рода в зависимости от значения."],"key":"Д","review":["Два значения -ище","«Топорище» как рукоять и «пожарище» как место после пожара относятся к среднему роду: крепкое топорище, мрачное пожарище.","Эти же формы могут увеличительно называть большой топор или пожар и наследовать мужской род исходного слова. Значение нужно установить по контексту."]},{"author":"К. Кноп","question":"Некоторые слова пишутся слитно или раздельно в зависимости от того, являются ли они прилагательными или частью причастного оборота. Например, допустимо как написание <em>долгоживущий</em>, так и <em>долго живущий</em>. Найдите в списке ещё одно слово с тем же свойством.","choices":["<em>свежевымытый</em>","<em>легковоспламеняющийся</em>","<em>малозначительный</em>","<em>краснознамённый</em>","<em>быстрорастворимый</em>."],"key":"Б","review":["Вместе или отдельно","Когда сочетание становится названием постоянного свойства, употребляется слитное написание «легковоспламеняющийся материал».","Если отдельно подчёркивается обстоятельство, например «легко воспламеняющийся от искры материал», наречие сохраняет собственный смысл. Это похоже на «долго живущий»."]},{"author":"Л. Фёдорова","question":"Современные русские фамилии подчиняются правилам написания прилагательных. Какие фамилии из следующего ряда нельзя считать современными русскими по этому признаку: 1) <em>Синицын</em>, 2) <em>Ельцин</em>, 3) <em>Живаго</em>, 4) <em>Дурново</em>, 5) <em>Польских</em>?","choices":["3, 4","2, 3, 4","3, 4, 5","1, 2","2, 3."],"key":"Б","review":["Старинные фамилии","Сопоставим записи фамилий с обычным современным написанием прилагательных. Вариант Ельцин сохраняет и после ц, а Живаго и Дурново — старые записи родительного окончания.","По этому орфографическому признаку выделяем 2, 3, 4. Он ничего не говорит о национальности носителя фамилии."]},{"author":"П. Аркадьев","question":"Даны старославянские слова и их переводы на русский язык: рѫка — <em>рука</em>, рѫкы — <em>ру́ки</em>, рѫцѣ — <em>две руки</em>, рабъ — <em>раб</em>, раби — <em>рабы</em>, раба — <em>два раба</em>, ноѕѣ — <em>две ноги,</em> роѕи — <em>рога́</em>, рога — <em>два рога</em>. Как будет по-старославянски <em>два врага, враги, две му́ки, му́ки</em>?","choices":["врага, враги, мѫкѣ, мѫки","врага, враѕѣ, мѫци, мѫкы","врага, враѕи, мѫцѣ, мѫци","врага, врагы, мѫцѣ, мѫкы","врага, враѕи, мѫцѣ, мѫкы."],"key":"Д","review":["Старинные формы","Сравни «рабъ — раба» и «рога — роѕи» с соответствующими формами в условии. У «врагъ» для двух получаем «врага», а во множественном перед и согласный меняется: «враѕи».","У «мѫка» чередование к/ц и двойственное окончание дают «мѫцѣ», а во множественном по образцу «рѫкы» получается «мѫкы»."]},{"author":"Е. Муравенко","question":"Даны японские слова в русской транскрипции с переводами: иэ-но нака-кара — <em>из дома</em>, иэ-но нака-ни — <em>в дом</em>, иэ-но соба дэ — <em>у дома</em>, иэ-но соба-ни — <em>к дому</em>, иэ-но усиро-дэ — <em>за домом</em>. Как по-японски будет <em>из-за дома</em>?","choices":["<em>иэ-но усиро-ни</em>","<em>иэ-но нака-дэ</em>","<em>иэ-но кара-дэ</em>","<em>иэ-но усиро-кара</em>","<em>иэ-но соба-кара</em>."],"key":"Г","review":["Из-за дома","«Иэ-но» задаёт ориентир — дом. На значение «позади» указывает «усиро» в выражении «за домом».","Исходное направление «из» передано «кара» в примере «из дома». Соединяем: «иэ-но усиро-кара»."]},{"author":"П. Аркадьев","question":"Склонение какого из этих существительных чем-то отличается от склонения других?","choices":["<em>рука</em>","<em>борода</em>","<em>нога</em>","<em>голова</em>","<em>губа</em>."],"key":"Д","review":["Ударение при склонении","Сравни винительный единственного числа: ру́ку, бо́роду, но́гу, го́лову. Во всех четырёх словах ударение перемещается с окончания на основу.","Слово «губа́» в обычном значении даёт «губу́». Оно отличается местом ударения в этой форме."]}], {"year":2001,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2001.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
